public class MyControl : UserControl
{
    public string DisplayName { get; set; }
    public int MaxItems { get; set; }

    private readonly StatusStrip _statusStrip;

    public MyControl()
    {
        _statusStrip = new StatusStrip();
        // .NET 9 changed StatusStrip default rendering; set explicitly to preserve .NET 8 look.
        _statusStrip.RenderMode = ToolStripRenderMode.Professional;
        Controls.Add(_statusStrip);
    }

    /// <summary>
    /// Shows a dropdown editor, guarding against the null control that
    /// .NET 9 now rejects with ArgumentNullException.
    /// </summary>
    public void ShowDropDown(IWindowsFormsEditorService editorService, Control dropDown)
    {
        if (dropDown is null)
            return;

        editorService.DropDownControl(dropDown);
    }

    // .NET 9+: prefer source-generated LibraryImport over DllImport for better
    // trimming, AOT support, and avoiding the runtime marshalling layer.
    [LibraryImport("user32.dll", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static partial bool SetWindowPos(
        IntPtr hWnd,
        IntPtr hWndInsertAfter,
        int x, int y, int cx, int cy,
        uint uFlags);
}

